<?php session_start();$AUTH_PASSWORD='';define('FM_ROOT_PATH',realpath(__DIR__));$ALLOW_ZIP=class_exists('ZipArchive');function get_abs($r=''){$p=FM_ROOT_PATH.($r!==''?DIRECTORY_SEPARATOR.trim(str_replace(['../','..\\',"\0"],'',(string)$r),'/\\'):'');$rp=realpath($p);return($rp&&strpos($rp,FM_ROOT_PATH)===0)?$rp:((!file_exists($p)&&strpos(realpath(dirname($p))?:'',FM_ROOT_PATH)===0)?$p:FM_ROOT_PATH);}function get_rel($a){return($a===FM_ROOT_PATH)?'':trim(str_replace('\\','/',substr($a,strlen(FM_ROOT_PATH))),'/');}function get_url($p='',$act='',$ex=[]){return basename($_SERVER['PHP_SELF']).'?'.http_build_query(array_filter(array_merge(['p'=>$p],$act?['action'=>$act]:[],$ex),fn($v)=>$v!==''));}function format_bytes($b){$u=['B','KB','MB','GB','TB'];return $b<=0?'0 B':round($b/(1024 **($p=min((int)floor(log($b,1024)),4))),2).' '.$u[$p];}function is_edit($e){return in_array($e,['txt','php','html','htm','css','js','json','xml','md','py','sql','sh','env','ini','conf','csv','yaml','yml','log','svg','htaccess']);}function delete_rec($t){if(!file_exists($t))return false;if(!is_dir($t))return@unlink($t);foreach(array_diff(scandir($t),['.','..'])as $f)delete_rec($t.DIRECTORY_SEPARATOR.$f);return@rmdir($t);}function get_dir_stats($dir){$s=$f=$d=0;if(is_dir($dir)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST)as $i){$i->isDir()?$d++:($f++&&($s+=$i->getSize()));}}return['size'=>$s,'files'=>$f,'dirs'=>$d];}if(!empty($AUTH_PASSWORD)){if(isset($_POST['login_pass'])){if($_POST['login_pass']===$AUTH_PASSWORD){$_SESSION['fm_logged']=true;header('Location: '.$_SERVER['PHP_SELF']);exit;}$login_err='Invalid password.';}if(($_GET['action']?? '')==='logout'){unset($_SESSION['fm_logged']);header('Location: '.$_SERVER['PHP_SELF']);exit;}if(empty($_SESSION['fm_logged'])){echo '<!doctype html><html><head><meta charset="utf-8"><title>Login</title></head><body><main><h1>BoringManager</h1>'.(!empty($login_err)?"<p style='color:#d32f2f;'>$login_err</p>":'');echo '<form method="POST"><label>Master Password</label><input type="password" name="login_pass" required autofocus><button type="submit">Unlock</button></form></main></body></html>';exit;}}$cur_abs=get_abs($_REQUEST['p']?? '');$cur_rel=get_rel($cur_abs);$msg=$_GET['msg']?? '';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['do_chunk_upload'],$_FILES['chunk_file'])){header('Content-Type: application/json');$fn=basename(trim(str_replace(["\0",'/','\\'],'',$_POST['file_name']?? '')));$idx=(int)($_POST['chunk_index']?? 0);$tmp=sys_get_temp_dir().DIRECTORY_SEPARATOR.'fm_'.md5(preg_replace('/[^a-zA-Z0-9_-]/','',$_POST['upload_token']?? '').$fn).'.tmp';$in=fopen($_FILES['chunk_file']['tmp_name'],'rb');$out=fopen($tmp,$idx===0?'wb':'ab');if($in&&$out){while(!feof($in))fwrite($out,fread($in,8192));}if($in)fclose($in);if($out)fclose($out);if($idx+1>=(int)($_POST['total_chunks']?? 1)){@rename($tmp,$cur_abs.DIRECTORY_SEPARATOR.$fn);echo json_encode(['status'=>'complete']);}else{echo json_encode(['status'=>'chunk_ok']);}exit;}if(isset($_POST['new_folder'])&&($fn=trim(str_replace(['/','\\','..'],'',$_POST['folder_name']?? '')))!==''){@mkdir($cur_abs.DIRECTORY_SEPARATOR.$fn,0755,true)?$msg="Folder created.":$msg="Failed creating folder.";}elseif(isset($_POST['new_file'])&&($fn=trim(str_replace(['/','\\','..'],'',$_POST['file_name']?? '')))!==''){file_put_contents($cur_abs.DIRECTORY_SEPARATOR.$fn,'')!==false?$msg="File created.":$msg="Failed creating file.";}elseif(isset($_POST['edit_file'])&&is_file($fa=get_abs($_POST['file']?? ''))){$ok=file_put_contents($fa,$_POST['content']?? '')!==false;header('Location: '.get_url($cur_rel,'edit',['file'=>get_rel($fa),'msg'=>$ok?'File saved successfully.':'Failed to save file.']));exit;}elseif(isset($_POST['rename_item'])&&file_exists($sa=get_abs($_POST['target']?? ''))){$nn=trim(str_replace(['/','\\','..'],'',$_POST['new_name']?? ''));if($nn!=='')@rename($sa,dirname($sa).DIRECTORY_SEPARATOR.$nn);header('Location: '.get_url($cur_rel));exit;}elseif(isset($_POST['delete_item'])&&($ta=get_abs($_POST['target']?? ''))!==FM_ROOT_PATH){delete_rec($ta);header('Location: '.get_url($cur_rel));exit;}elseif(isset($_POST['zip_item'])&&$ALLOW_ZIP&&file_exists($sa=get_abs($_POST['target']?? ''))){$zip=new ZipArchive();if($zip->open($sa.'.zip',ZipArchive::CREATE|ZipArchive::OVERWRITE)===true){if(is_dir($sa)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sa,4096),1)as $f){$r=substr($f->getPathname(),strlen($sa)+1);$f->isDir()?$zip->addEmptyDir($r):$zip->addFile($f->getPathname(),$r);}}else{$zip->addFile($sa,basename($sa));}$zip->close();$msg='Archived.';}}elseif(isset($_POST['unzip_item'])&&$ALLOW_ZIP&&is_file($sa=get_abs($_POST['target']?? ''))){$zip=new ZipArchive();if($zip->open($sa)===true){$zip->extractTo(dirname($sa));$zip->close();$msg='Extracted.';}}}$act=$_GET['action']?? 'list';if($act==='download'&&is_file($fa=get_abs($_GET['file']?? ''))){header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($fa).'"');header('Content-Length: '.filesize($fa));readfile($fa);exit;}if($act==='raw'&&is_file($fa=get_abs($_GET['file']?? ''))){$ext=strtolower(pathinfo($fa,PATHINFO_EXTENSION));$m=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','webp'=>'image/webp','svg'=>'image/svg+xml','mp3'=>'audio/mpeg','mp4'=>'video/mp4','pdf'=>'application/pdf','txt'=>'text/plain','json'=>'application/json'];header('Content-Type: '.($m[$ext]?? 'text/plain'));readfile($fa);exit;} ?><!doctypehtml><html><head><meta charset="utf-8"><meta content="width=device-width,initial-scale=1"name="viewport"><title>BoringManager</title><link href="https://cdn.jsdelivr.net/npm/simple.css@3/dist/simple.min.css"rel="stylesheet"></head><body><header><nav><a href="<?=get_url()?>"><strong>Root</strong></a><?php $accum='';foreach(array_filter(explode('/',$cur_rel))as $seg):$accum.=($accum===''?'':'/').$seg; ?>/ <a href="<?=get_url($accum)?>"><?=htmlspecialchars($seg)?></a><?php endforeach; ?><?php if(!empty($AUTH_PASSWORD)): ?><a href="<?=get_url($cur_rel,'logout')?>"style="float:right">Logout</a><?php endif; ?></nav><h1>BoringManager</h1></header><main><?php if(!empty($msg)): ?><p><mark><?=htmlspecialchars($msg)?></mark></p><?php endif; ?><?php if($act==='info'&&file_exists($ta=get_abs($_GET['target']?? ''))):$is_d=is_dir($ta);$st=$is_d?get_dir_stats($ta):['size'=>filesize($ta),'files'=>1,'dirs'=>0]; ?><h3>Info:<?=htmlspecialchars(basename($ta))?></h3><ul><li><strong>Type:</strong><?=$is_d?'Directory':'File ('.strtoupper(pathinfo($ta,PATHINFO_EXTENSION)).')'?></li><li><strong>Path:</strong> /<?=htmlspecialchars(get_rel($ta))?></li><li><strong>Total Size:</strong><?=format_bytes($st['size'])?>(<?=number_format($st['size'])?>B)</li><li><strong>All Subpath Files:</strong><?=$st['files']?>file(s)<?=$is_d?', '.$st['dirs'].' folder(s)':''?></li><li><strong>Permissions:</strong> <code><?=substr(sprintf('%o',fileperms($ta)),-4)?></code> (R:<?=is_readable($ta)?'Yes':'No'?>, W:<?=is_writable($ta)?'Yes':'No'?>)</li><li><strong>Last Modified:</strong><?=date('Y-m-d H:i:s',filemtime($ta))?></li></ul><p><a href="<?=get_url($cur_rel)?>"><button type="button">Back</button></a></p><?php elseif($act==='edit'&&is_file($fa=get_abs($_GET['file']?? ''))&&is_edit(strtolower(pathinfo($fa,PATHINFO_EXTENSION)))): ?><h3>Edit:<?=htmlspecialchars(basename($fa))?></h3><form method="POST"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="file"value="<?=htmlspecialchars(get_rel($fa))?>"type="hidden"><textarea name="content"rows="18"style="width:100%;font-family:monospace"><?=htmlspecialchars(file_get_contents($fa))?></textarea><p><button type="submit"name="edit_file"value="1">Save</button> <a href="<?=get_url($cur_rel)?>"><button type="button">Cancel</button></a></p></form><?php elseif($act==='view'&&is_file($fa=get_abs($_GET['file']?? ''))):$ext=strtolower(pathinfo($fa,PATHINFO_EXTENSION)); ?><h3>Preview:<?=htmlspecialchars(basename($fa))?>(<?=format_bytes(filesize($fa))?>)</h3><p><a href="<?=get_url($cur_rel,'info',['target'=>get_rel($fa)])?>"><button type="button">Info</button></a><?php if(is_edit($ext)): ?><a href="<?=get_url($cur_rel,'edit',['file'=>get_rel($fa)])?>"><button type="button">Edit</button></a><?php endif; ?><a href="<?=get_url($cur_rel,'download',['file'=>get_rel($fa)])?>"><button type="button">Download</button></a> <a href="<?=get_url($cur_rel)?>"><button type="button">Back</button></a></p><?php if(in_array($ext,['jpg','jpeg','png','gif','webp','svg'])): ?><img src="<?=get_url($cur_rel,'raw',['file'=>get_rel($fa)])?>"style="max-width:100%"><?php elseif(in_array($ext,['mp3','wav','ogg'])): ?><audio controls style="width:100%"><source src="<?=get_url($cur_rel,'raw',['file'=>get_rel($fa)])?>"></audio><?php elseif(in_array($ext,['mp4','webm'])): ?><video controls style="max-width:100%"><source src="<?=get_url($cur_rel,'raw',['file'=>get_rel($fa)])?>"></video><?php elseif($ext==='pdf'): ?><iframe src="<?=get_url($cur_rel,'raw',['file'=>get_rel($fa)])?>"style="width:100%;height:500px;border:none"></iframe><?php else: ?><pre><code><?=htmlspecialchars(file_get_contents($fa))?></code></pre><?php endif; ?><?php elseif($act==='rename'&&file_exists($ta=get_abs($_GET['target']?? ''))): ?><h3>Rename:<?=htmlspecialchars(basename($ta))?></h3><form method="POST"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="target"value="<?=htmlspecialchars(get_rel($ta))?>"type="hidden"><input name="new_name"value="<?=htmlspecialchars(basename($ta))?>"autofocus required><p><button type="submit"name="rename_item"value="1">Save</button> <a href="<?=get_url($cur_rel)?>"><button type="button">Cancel</button></a></p></form><?php else:$q=trim($_GET['q']?? '');$items=[];if($q!==''&&is_dir($cur_abs)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($cur_abs,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST)as $f){if(stripos($f->getFilename(),$q)!==false){$path=$f->getPathname();$is_d=$f->isDir();$items[]=['name'=>$f->getFilename(),'path'=>$path,'is_dir'=>$is_d,'size'=>$is_d?0:$f->getSize(),'mtime'=>$f->getMTime(),'perms'=>substr(sprintf('%o',$f->getPerms()),-4),'rel'=>get_rel($path),'ext'=>strtolower($f->getExtension())];}}}elseif(is_dir($cur_abs)){foreach(array_diff(scandir($cur_abs)?:[],['.','..'])as $name){$path=$cur_abs.DIRECTORY_SEPARATOR.$name;$is_d=is_dir($path);$items[]=['name'=>$name,'path'=>$path,'is_dir'=>$is_d,'size'=>$is_d?0:filesize($path),'mtime'=>filemtime($path),'perms'=>substr(sprintf('%o',fileperms($path)),-4),'rel'=>get_rel($path),'ext'=>strtolower(pathinfo($path,PATHINFO_EXTENSION))];}}usort($items,fn($a,$b)=>$a['is_dir']===$b['is_dir']?strcasecmp($a['name'],$b['name']):($a['is_dir']?-1:1)); ?><section><form style="display:flex;gap:.5rem;margin-bottom:1rem"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="q"value="<?=htmlspecialchars($q)?>"type="search"placeholder="Search subpaths..."><button type="submit">Search</button><?php if($q!==''): ?><a href="<?=get_url($cur_rel)?>"><button type="button">Clear</button></a><?php endif; ?></form><details style="margin-bottom:1rem"><summary>Upload / Create</summary><div style="display:flex;flex-wrap:wrap;gap:1rem;margin-top:.5rem"><form style="display:flex;gap:.5rem;align-items:center"onsubmit="startChunkUpload(event)"><input type="file"id="cf"multiple required><button type="submit">Upload</button></form><form method="POST"style="display:flex;gap:.5rem"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="folder_name"placeholder="Folder"required><button type="submit"name="new_folder"value="1">+ Folder</button></form><form method="POST"style="display:flex;gap:.5rem"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="file_name"placeholder="File"required><button type="submit"name="new_file"value="1">+ File</button></form></div><p id="cp"style="display:none;margin-top:.5rem"><mark id="cpt">Uploading...</mark></p></details></section><h3>Total:<?=count($items ??[])?>item(s)</h3><div style="overflow-x:auto"><table><thead><tr><th>Name</th><th>Size</th><th>Modified</th><th>Perms</th><th>Actions</th></tr></thead><tbody><?php if($cur_rel!==''&&$q===''): ?><tr><td colspan="5"><a href="<?=get_url(dirname($cur_rel)==='.'?'':dirname($cur_rel))?>">📁 .. (Parent)</a></td></tr><?php endif; ?><?php if(empty($items)): ?><tr><td colspan="5"style="text-align:center">No items found.</td></tr><?php endif; ?><?php foreach($items as $it): ?><tr><td><a href="<?=$it['is_dir']?get_url($it['rel']):get_url($cur_rel,'view',['file'=>$it['rel']])?>"><?=$it['is_dir']?'📁 <strong>'.htmlspecialchars($it['name']).'</strong>':'📄 '.htmlspecialchars($it['name'])?></a><?php if($q!==''): ?><br><small style="color:gray">/<?=htmlspecialchars($it['rel'])?></small><?php endif; ?></td><td><?=$it['is_dir']?'-':format_bytes($it['size'])?></td><td><small><?=date('Y-m-d H:i',$it['mtime'])?></small></td><td><code><?=$it['perms']?></code></td><td style="white-space:nowrap"><details><summary>Actions</summary><div style="display:inline-flex;gap:.35rem;align-items:center;padding:.25rem 0"><a href="<?=get_url($cur_rel,'info',['target'=>$it['rel']])?>">Info</a><?php if(!$it['is_dir']): ?>| <a href="<?=get_url($cur_rel,'view',['file'=>$it['rel']])?>">View</a><?php if(is_edit($it['ext'])): ?>| <a href="<?=get_url($cur_rel,'edit',['file'=>$it['rel']])?>">Edit</a><?php endif; ?>| <a href="<?=get_url($cur_rel,'download',['file'=>$it['rel']])?>">Download</a><?php endif; ?>| <a href="<?=get_url($cur_rel,'rename',['target'=>$it['rel']])?>">Rename</a><?php if($ALLOW_ZIP&&$it['ext']==='zip'): ?>|<form method="POST"style="display:inline"onsubmit='return confirm("Extract zip?")'><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="target"value="<?=htmlspecialchars($it['rel'])?>"type="hidden"><button type="submit"name="unzip_item"value="1"style="padding:.15rem .4rem;font-size:.8rem">Unzip</button></form><?php elseif($ALLOW_ZIP): ?>|<form method="POST"style="display:inline"><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="target"value="<?=htmlspecialchars($it['rel'])?>"type="hidden"><button type="submit"name="zip_item"value="1"style="padding:.15rem .4rem;font-size:.8rem">Zip</button></form><?php endif; ?>|<form method="POST"style="display:inline"onsubmit='return confirm("Delete<?=htmlspecialchars($it['name'],ENT_QUOTES)?>?")'><input name="p"value="<?=htmlspecialchars($cur_rel)?>"type="hidden"><input name="target"value="<?=htmlspecialchars($it['rel'])?>"type="hidden"><button type="submit"name="delete_item"value="1"style="padding:.15rem .4rem;font-size:.8rem;background:#c62828;color:#fff">Del</button></form></div></details></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main><script>async function startChunkUpload(e) {e.preventDefault();const files = document.getElementById('cf').files, prog = document.getElementById('cp'), txt = document.getElementById('cpt');if (!files.length) return;prog.style.display = 'block'; const sz = 2 * 1024 * 1024;for (let f = 0; f < files.length; f++) {const file = files[f], chunks = Math.ceil(file.size / sz) || 1, tok = Date.now() + '_' + f;for (let i = 0; i < chunks; i++) {const fd = new FormData();fd.append('do_chunk_upload', '1'); fd.append('p', '<?=htmlspecialchars($cur_rel,ENT_QUOTES)?>');fd.append('file_name', file.name); fd.append('chunk_index', i); fd.append('total_chunks', chunks); fd.append('upload_token', tok);fd.append('chunk_file', file.slice(i * sz, Math.min((i + 1) * sz, file.size)), file.name);txt.innerText = `Uploading (${f + 1}/${files.length}): ${file.name} - ${Math.round(((i + 1) / chunks) * 100)}%`;await fetch(window.location.pathname, { method: 'POST', body: fd });}}window.location.reload();}</script></body></html>
